import sys
from collections import defaultdict

sys.setrecursionlimit(2 * 10**5)

def dfs(v, p, dist, adj, a):
    cost = dist * a[v - 1]
    for u in adj[v]:
        if u != p:
            cost += dfs(u, v, dist + 1, adj, a)
    return cost

def main():
    n = int(input())
    a = list(map(int, input().split()))
    adj = defaultdict(list)

    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    max_cost = 0
    for i in range(n):
        max_cost = max(max_cost, dfs(i + 1, -1, 0, adj, a))

    print(max_cost)

if __name__ == "__main__":
    main()
